import fs from 'fs';
import path from 'path';

function writeBase64ToFile(filepath, base64Data) {
  const buffer = Buffer.from(base64Data, 'base64');
  fs.writeFileSync(filepath, buffer);
  console.log(`Fixed ${filepath}`);
}

writeBase64ToFile('public/icon-192.png', '');
writeBase64ToFile('public/icon-512.png', '');
writeBase64ToFile('public/screenshot-desktop.png', '');
writeBase64ToFile('public/screenshot-mobile.png', '');
